import argparse
import sys

from wpctl.libs import config
from wpctl.run import run
from wpctl.utils.custom_logger import get_logger

logger = get_logger(__name__)


def _validate_env() -> None:
    """必須の認証情報（環境変数または設定ファイル）が揃っているか検証する。

    Raises:
        SystemExit: 未設定の項目が存在する場合
    """
    missing = config.get_missing_keys()
    if missing:
        for var in missing:
            print(
                f"Error: {var} が設定されていません。"
                f"`wpctl auth set` で設定するか、環境変数を設定してください。",
                file=sys.stderr,
            )
        sys.exit(1)


def _build_parser() -> argparse.ArgumentParser:
    """CLIパーサーを構築する。

    Returns:
        ArgumentParser: 構築済みのパーサー
    """
    parser = argparse.ArgumentParser(
        prog="wpctl",
        description="WordPress APIを活用して記事を投稿・管理するCLIツール",
    )
    subparsers = parser.add_subparsers(dest="command")

    post_parser = subparsers.add_parser("post", help="記事を管理する")
    post_subparsers = post_parser.add_subparsers(dest="subcommand")

    create_parser = post_subparsers.add_parser("create", help="記事を投稿する")
    create_parser.add_argument(
        "file_path", metavar="FilePath", nargs="?", default=None,
        help="投稿するファイルのパス（--content と排他）",
    )
    create_parser.add_argument(
        "--content", "-c",
        default=None,
        help="投稿するHTML文字列（FilePath と排他）",
    )
    create_parser.add_argument(
        "--title", "-t",
        default=None,
        help="タイトル（省略時: Markdownの第一見出し / デフォルト: タイトル未設定）",
    )
    create_parser.add_argument(
        "--status", "-s",
        choices=["draft", "publish"],
        default="draft",
        help="記事のステータス（デフォルト: draft）",
    )
    create_parser.add_argument(
        "--excerpt", "-e",
        default=None,
        help="記事の抜粋",
    )
    create_parser.add_argument(
        "--categories",
        default=None,
        help="カテゴリーIDまたは名前（カンマ区切り、例: 1,2,3）",
    )
    create_parser.add_argument(
        "--tags",
        default=None,
        help="タグIDまたは名前（カンマ区切り、例: tech,python）",
    )
    create_parser.add_argument(
        "--content-format",
        dest="content_format",
        choices=["html", "md"],
        default="html",
        help="--content の形式（html / md）（デフォルト: html）",
    )

    update_parser = post_subparsers.add_parser("update", help="記事を更新する")
    update_parser.add_argument(
        "file_path", metavar="FilePath", nargs="?", default=None,
        help="投稿するファイルのパス（--content と排他）",
    )
    update_parser.add_argument(
        "--content", "-c",
        default=None,
        help="投稿するHTML文字列（FilePath と排他）",
    )
    update_parser.add_argument(
        "--id", dest="post_id", type=int, required=True, help="更新する記事のID"
    )
    update_parser.add_argument(
        "--title", "-t",
        default=None,
        help="タイトル（省略時: Markdownの第一見出し / デフォルト: タイトル未設定）",
    )
    update_parser.add_argument(
        "--status", "-s",
        choices=["draft", "publish"],
        default=None,
        help="記事のステータス（省略時: 現在のステータスを維持）",
    )
    update_parser.add_argument(
        "--excerpt", "-e",
        default=None,
        help="記事の抜粋",
    )
    update_parser.add_argument(
        "--categories",
        default=None,
        help="カテゴリーIDまたは名前（カンマ区切り、例: 1,2,3）",
    )
    update_parser.add_argument(
        "--tags",
        default=None,
        help="タグIDまたは名前（カンマ区切り、例: tech,python）",
    )
    update_parser.add_argument(
        "--content-format",
        dest="content_format",
        choices=["html", "md"],
        default="html",
        help="--content の形式（html / md）（デフォルト: html）",
    )

    get_parser = post_subparsers.add_parser("get", help="記事一覧を取得する")
    get_parser.add_argument(
        "--search", default=None,
        help="検索キーワード",
    )
    get_parser.add_argument(
        "--status", "-s",
        default="any",
        help="ステータスフィルター（publish / draft / any）（デフォルト: any）",
    )
    get_parser.add_argument(
        "--per-page", dest="per_page", type=int, default=10,
        help="1ページあたりの件数（デフォルト: 10）",
    )
    get_parser.add_argument(
        "--page", type=int, default=1,
        help="ページ番号（デフォルト: 1）",
    )

    show_parser = post_subparsers.add_parser("show", help="記事の詳細を取得する")
    show_parser.add_argument(
        "post_id", metavar="ID", type=int,
        help="取得する記事のID",
    )
    show_parser.add_argument(
        "--format", "-f",
        dest="format",
        choices=["text", "md"],
        default="text",
        help="コンテンツの出力フォーマット（text / md）（デフォルト: text）",
    )

    auth_parser = subparsers.add_parser("auth", help="認証情報を管理する")
    auth_subparsers = auth_parser.add_subparsers(dest="subcommand")

    auth_set_parser = auth_subparsers.add_parser("set", help="認証情報を設定する")
    auth_set_parser.add_argument(
        "--site-url", dest="site_url", default=None,
        help="WordPressサイトURL（未指定時は対話入力）",
    )
    auth_set_parser.add_argument(
        "--user", dest="user", default=None,
        help="WordPressユーザー名（未指定時は対話入力）",
    )
    auth_set_parser.add_argument(
        "--app-password", dest="app_password", default=None,
        help="WordPressアプリケーションパスワード（未指定時は対話入力）",
    )
    auth_set_parser.add_argument(
        "--scope",
        choices=["project", "user"],
        default="project",
        help="保存先（project: カレントディレクトリ / user: ホームディレクトリ）"
        "（デフォルト: project）",
    )

    auth_subparsers.add_parser("status", help="認証情報の設定状況を確認する")

    return parser


def main():
    """エントリーポイント。CLI引数を解析してrunに渡す。"""
    parser = _build_parser()
    args = parser.parse_args()

    if args.command is None:
        parser.print_help()
        return

    if args.command == "post":
        _validate_env()
    logger.info(f"wpctl {args.command} {args.subcommand}")
    run(args)


if __name__ == "__main__":
    main()
